def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(length, separators):
        result = []
        start = 0
        for i in separators:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < length:
            result.append((start, length))
        return result

    row_parts = segments(h, sep_rows)
    col_parts = segments(w, sep_cols)

    regions = []
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            tile = [row[c0:c1] for row in grid[r0:r1]]
            counts = {}
            for row in tile:
                for value in row:
                    counts[value] = counts.get(value, 0) + 1
            background = max(counts, key=counts.get)
            score = sum(value != background for row in tile for value in row)
            regions.append((score, r0, r1, c0, c1, tile))

    _, _, _, _, _, seed = max(regions, key=lambda item: item[0])
    out = [row[:] for row in grid]
    for _, r0, r1, c0, c1, _ in regions:
        for dr in range(r1 - r0):
            for dc in range(c1 - c0):
                out[r0 + dr][c0 + dc] = seed[dr][dc]
    return out
